style.css:
@-moz-document domain("youtube.com") {
/* Apply the background to the core body and app container */
    body, ytd-app {
        background-image: url("https://e0.pxfuel.com/wallpapers/461/859/desktop-wallpaper-black-red-shards-orange-shards.jpg") !important;
        background-size: cover !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important; /* The image stays still while you scroll */
        background-position: center !important;
    }

    /* --- Necessary UI Fixes to Make the Background Visible --- */

    /* Ensure the background of the main masthead (top bar) is transparent */
    #masthead-container.ytd-app, #masthead.style-scope.ytd-app {
        background-color: transparent !important;
    }

    /* Make the content containers transparent */
    #primary.style-scope.ytd-watch-flexy,
    #secondary.style-scope.ytd-watch-flexy,
    ytd-browse,
    ytd-page-manager {
        background-color: transparent !important;
    }

    /* Adjust player bar to work with the text and controls on top */
    /* Ensure the description and comments panels have a dark, semi-transparent background for readability */
    ytd-watch-metadata #description-inner.ytd-watch-metadata,
    ytd-item-section-renderer[page-subtype="watch"] {
        background-color: rgba(0, 0, 0, 0.8) !important;
        border-radius: 12px;
        padding: 10px;
        margin-top: 10px;
    }

    /* --- Optional: Align UI with the image colors --- */
    
    /* Make the top line of the player orange */
    #masthead-container.ytd-app {
        border-bottom: 2px solid #ff5722 !important; /* An orange accent */
    }

    /* Make video text titles white/orange for contrast */
    #video-title {
        color: #fff !important;
    }
    
    /* Color specific buttons orange */
    ytd-button-renderer.style-suggestive[is-paper-button] #text.ytd-button-renderer {
        color: #ff5722 !important;
    }
}
